"use client";
import Link from "next/link";
import { useActionState, useState } from "react";
import { useFormStatus } from "react-dom";
import Card from "../components/ui/Card";

export function DexaAppointmentDetailScreen({item}){return <Shell><Header/><Card><h2 className="font-extrabold">{item?"Scheduled appointment":"Not scheduled"}</h2><p className="mt-1 text-sm text-[var(--text-secondary)]">{formatDexaAppointmentSummary(item)}</p>{item?.timezone&&<p className="mt-1 text-xs text-[var(--text-muted)]">{item.timezone}</p>}</Card>{item&&<><Card><p className="text-xs font-bold uppercase text-[var(--text-muted)]">Reminders</p><p className="mt-1 text-sm font-semibold">{formatReminders(item)}</p></Card>{item.preparationNote&&<Card><p className="text-xs font-bold uppercase text-[var(--text-muted)]">Preparation note</p><p className="mt-1 text-sm">{item.preparationNote}</p></Card>}</>}<Link className="flex min-h-12 items-center justify-center rounded-2xl bg-[var(--primary)] font-extrabold text-white" href="/profile/operating-plan/execution/dexa?edit=1">{item?"Edit schedule":"Schedule DEXA"}</Link></Shell>}
export function DexaAppointmentEditorScreen({action,item,minDate}){const[state,formAction]=useActionState(action,{message:null,values:null});const value=state.values??{plannedDate:item?.preferredSchedule?.date??"",localTime:item?.preferredSchedule?.timeOfDay??"",reminderPreferences:item?.reminderPreferences??[],uploadReminder:item?.uploadReminder??false,preparationNote:item?.preparationNote??""};const[date,setDate]=useState(value.plannedDate);return <main className="app-surface min-h-screen"><form action={formAction} className="mx-auto max-w-[393px] space-y-5 px-4 pb-28 pt-10"><Header/>{state.message&&<p className="rounded-xl bg-[var(--surface-muted)] p-3 text-sm font-semibold">{state.message}</p>}<Section title="Appointment"><Field label="Future date" name="plannedDate" type="date" min={minDate} value={date} onChange={(e)=>setDate(e.target.value)}/><Field label="Time (optional)" name="localTime" type="time" defaultValue={value.localTime}/></Section>{date&&<Section title="Reminders">{[["week_before","1 week before"],["day_before","1 day before"],["morning_of","Morning of"]].map(([id,label])=><Check key={id} name="reminders" value={id} label={label} defaultChecked={value.reminderPreferences?.includes(id)}/>) }<Check name="uploadReminder" label="Remind me after the appointment to upload my DEXA results" defaultChecked={value.uploadReminder}/></Section>}<Section title="Preparation note"><textarea className="min-h-24 w-full rounded-xl border border-[var(--divider)] bg-[var(--surface-muted)] p-3" maxLength={1000} name="preparationNote" defaultValue={value.preparationNote}/></Section><Submit label={date?"Save schedule":"Clear schedule"}/></form></main>}
function Shell({children}){return <main className="app-surface min-h-screen"><div className="mx-auto max-w-[393px] space-y-5 px-4 pb-28 pt-10">{children}</div></main>}
function Header(){return <><Link className="inline-flex min-h-11 items-center text-sm font-semibold text-[var(--text-secondary)]" href="/profile/operating-plan">← Operating Plan</Link><header><p className="text-xs font-extrabold uppercase tracking-widest text-[var(--primary)]">DEXA Execution</p><h1 className="mt-2 text-3xl font-extrabold">Next DEXA Scan</h1><p className="mt-2 text-sm text-[var(--text-secondary)]">Plan an optional future appointment. Completed scans remain in Evidence.</p></header></>}
function Section({title,children}){return <section className="space-y-3 rounded-2xl bg-[var(--surface-elevated)] p-4"><h2 className="font-extrabold">{title}</h2>{children}</section>}
function Field({label,...props}){return <label><span className="mb-2 block text-xs font-bold text-[var(--text-secondary)]">{label}</span><input className="min-h-12 w-full rounded-xl border border-[var(--divider)] bg-[var(--surface-muted)] px-3" {...props}/></label>}
function Check({label,...props}){return <label className="flex min-h-11 items-center gap-3 text-sm font-semibold"><input className="h-5 w-5" type="checkbox" {...props}/><span>{label}</span></label>}
function Submit({label}){const{pending}=useFormStatus();return <button disabled={pending} className="min-h-12 w-full rounded-2xl bg-[var(--primary)] font-extrabold text-white disabled:opacity-60" type="submit">{pending?"Saving…":label}</button>}
function formatReminders(item){const names={week_before:"1 week before",day_before:"1 day before",morning_of:"Morning of"};const values=(item.reminderPreferences??[]).map((value)=>names[value]);if(item.uploadReminder)values.push("Upload-results reminder");return values.join(" · ")||"None";}
function formatDexaAppointmentSummary(item){if(!item)return"Not scheduled";const date=new Date(`${item.preferredSchedule.date}T12:00:00`).toLocaleDateString("en-US",{month:"long",day:"numeric"});const raw=item.preferredSchedule.timeOfDay;const time=raw?new Date(`2000-01-01T${raw}:00`).toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"}):"";return[date,time].filter(Boolean).join(" · ");}
